package com.jnapanam.sportszone.tournament.dto;import com.jnapanam.sportszone.tournament.model.*;import java.time.Instant;import java.util.UUID;public record OrganizerApplicationResponse(UUID id,UUID userId,String applicantName,String organizationName,String experience,String contactNumber,OrganizerStatus status,String reviewNote,Instant appliedAt){public static OrganizerApplicationResponse from(OrganizerApplication a){return new OrganizerApplicationResponse(a.getId(),a.getUser().getId(),a.getUser().getFullName(),a.getOrganizationName(),a.getExperience(),a.getContactNumber(),a.getStatus(),a.getReviewNote(),a.getAppliedAt());}}
